import re

def parse_ini_strict(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    sections = {}
    current_section = ""
    for line_number, line in enumerate(text.splitlines(keep=False)):
        # Remove trailing \r if present
        if line.endswith('\r'):
            line = line[:-1]
        stripped_line = line.strip(' \t')
        if not stripped_line:
            continue
        if stripped_line.startswith(';') or stripped_line.startswith('#'):
            continue
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            section_name = stripped_line[1:-1].strip(' \t')
            if not section_name or '[' in section_name or ']' in section_name:
                raise ValueError(f"Invalid section header at line {line_number + 1}")
            current_section = section_name
            if current_section not in sections:
                sections[current_section] = {}
            continue
        if '=' not in stripped_line:
            raise ValueError(f"Missing '=' in line {line_number + 1}")

        # Find the first '='
        first_eq = stripped_line.find('=')
        key_part = stripped_line[:first_eq].strip(' \t')
        key = key_part.lower()
        if not key_part:
            raise ValueError(f"Empty key in line {line_number + 1}")

        # Check if key already exists in current section
        if key in sections[current_section]:
            raise ValueError(f"Duplicate key '{key_part}' in section '{current_section}' at line {line_number + 1}")

        raw_value = stripped_line[first_eq + 1:]

        # Determine quoted or unquoted
        v = raw_value.strip(' \t')
        if v.startswith('"'):
            # Process quoted value
            quote_pos = 1
            escaped = False
            value = []
            while quote_pos < len(raw_value):
                c = raw_value[quote_pos]
                if escaped:
                    if c == 'n':
                        value.append('\n')
                    elif c == '"':
                        value.append('"')
                    elif c == '\\':
                        value.append('\\')
                    else:
                        raise ValueError(f"Invalid escape sequence in quoted value at line {line_number + 1}")
                    escaped = False
                elif c == '\\':
                    escaped = True
                elif c == '"' and not escaped:
                    # End of quoted value
                    quote_pos += 1
                    break
                else:
                    value.append(c)
                quote_pos += 1
            if escaped:
                raise ValueError(f"Unterminated escape sequence in quoted value at line {line_number + 1}")
            if quote_pos >= len(raw_value) or raw_value[quote_pos - 1] != '"':
                raise ValueError(f"Missing closing quote in quoted value at line {line_number + 1}")

            # Check remaining part after quote
            remaining = raw_value[quote_pos:].strip(' \t')
            if remaining and not remaining.startswith(';') and not remaining.startswith('#'):
                raise ValueError(f"Invalid content after quoted value at line {line_number + 1}")

            value_str = ''.join(value)
        else:
            # Process unquoted value
            comment_match = re.search(r'(?<=[ \t])(;|#)', raw_value)
            if comment_match:
                value_str = raw_value[:comment_match.start()].strip(' \t')
            else:
                value_str = raw_value.strip(' \t')

        sections[current_section][key] = value_str

    # Remove empty section if it's empty
    if "" in sections and not sections[""]:
        del sections[""]

    return sections
