To solve the problem of integer partitions efficiently, we use dynamic programming for `count_partitions` and a recursive, lex-order-aware selection strategy for `kth_partition`. For `count_partitions`, we memoize the number of valid partitions for given `n`, `max_part`, and `distinct` constraints using recurrence relations. For `kth_partition`, we iteratively determine each part by calculating how many partitions start with a given prefix, leveraging the counts without generating all partitions.

```python
import functools
import math

def count_partitions(n, max_part=None, distinct=False):
    if not isinstance(n, int) or n < 0:
        raise ValueError
    if max_part is not None and (not isinstance(max_part, int) or max_part < 0):
        raise ValueError
    if distinct and max_part is not None and max_part < 0:
        raise ValueError
    if n == 0:
        return 1
    if max_part is None:
        max_part = n
    else:
        max_part = min(max_part, n)
    if max_part <= 0:
        return 0
    if distinct:
        @functools.lru_cache(maxsize=None)
        def dp_distinct(n, max_p):
            if n == 0:
                return 1
            if n < 0 or max_p <= 0:
                return 0
            include = dp_distinct(n - max_p, max_p - 1)
            exclude = dp_distinct(n, max_p - 1)
            return include + exclude
        return dp_distinct(n, max_part)
    else:
        @functools.lru_cache(maxsize=None)
        def dp_standard(n, max_p):
            if n == 0:
                return 1
            if n < 0 or max_p <= 0:
                return 0
            include = dp_standard(n - max_p, max_p)
            exclude = dp_standard(n, max_p - 1)
            return include + exclude
        return dp_standard(n, max_part)

def kth_partition(n, k, max_part=None, distinct=False):
    if not isinstance(n, int) or n < 0 or not isinstance(k, int):
        raise ValueError
    if k < 0:
        raise ValueError
    count = count_partitions(n, max_part, distinct)
    if k >= count:
        raise ValueError
    if n == 0:
        return ()
    if max_part is None:
        max_part = n
    else:
        max_part = min(max_part, n)
    if max_part <= 0:
        return ()
    result = []

    def recurse(remaining, target, current_max, idx, distinct_flag):
        if remaining == 0:
            return []
        for p in range(1, current_max + 1):
            if distinct_flag:
                new_remaining = target - p
                new_max = p - 1
                cnt = count_partitions(new_remaining, new_max, distinct_flag)
            else:
                new_remaining = target - p
                new_max = min(p, current_max)
                cnt = count_partitions(new_remaining, new_max, distinct_flag)
            if cnt > idx:
                result.append(p)
                next_target = target - p
                next_max = p if not distinct_flag else p - 1
                next_idx = idx
                inner = recurse(next_target, next_max, next_max, next_idx, distinct_flag)
                if inner is not None:
                    return tuple(result + inner)
            else:
                idx -= cnt
        return None

    path = recurse(n, n, max_part, k, distinct)
    return path
