from collections import defaultdict

def route_info(n, edges, src, dst):
    # Validate inputs
    if not isinstance(n, int) or n < 1:
        raise ValueError("Invalid n")
    if not (isinstance(edges, list) or isinstance(edges, tuple)):
        raise ValueError("Invalid edges")
    for edge in edges:
        if not (isinstance(edge, tuple) or isinstance(edge, list)) or len(edge) != 3:
            raise ValueError("Invalid edge")
        u, v, w = edge
        if not isinstance(u, int) or not isinstance(v, int) or not isinstance(w, int):
            raise ValueError("Edge elements must be integers")
        if not (0 <= u < n and 0 <= v < n):
            raise ValueError("Node out of range")
        if w < 1:
            raise ValueError("Weight must be at least 1")
    if not isinstance(src, int) or not isinstance(dst, int):
        raise ValueError("Source or destination invalid")
    if not (0 <= src < n and 0 <= dst < n):
        raise ValueError("Source or destination out of range")

    if src == dst:
        return (0, 1, [src])

    # Initialize data structures
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    INF = float('inf')
    MOD = 1_000_000_007

    dist = [INF] * n
    count = [0] * n
    prev = [-1] * n

    dist[src] = 0
    count[src] = 1
    heap = [(0, src)]

    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                count[v] = count[u]
                prev[v] = u
                heapq.heappush(heap, (dist[v], v))
            elif dist[v] == dist[u] + w:
                count[v] = (count[v] + count[u]) % MOD
                # Check if path through u is lex smaller
                path_u = get_path(src, u, prev)
                path_prev = get_path(src, prev[v], prev) if prev[v] != -1 else [src]
                path_u += [u, v]
                path_prev += [prev[v], v]
                if is_lex_smaller(path_u, path_prev):
                    prev[v] = u

    if dist[dst] == INF:
        return None

    path = reconstruct_path(src, dst, prev)
    return (dist[dst], count[dst], path)

def is_lex_smaller(path_u, path_prev):
    min_len = min(len(path_u), len(path_prev))
    for i in range(min_len):
        if path_u[i] < path_prev[i]:
            return True
        elif path_u[i] > path_prev[i]:
            return False
    return len(path_u) < len(path_prev)

def get_path(src, dst, prev):
    path = []
    current = dst
    while current != src:
        path.append(current)
        current = prev[current]
    path.append(src)
    return path[::-1]

def reconstruct_path(src, dst, prev):
    if prev[dst] == -1 and dst != src:
        return None
    path = []
    current = dst
    while current != src:
